/// <summary>
/// PricingAttribute of table <c>EcoResProductVariantSize</c> field Size.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeEcoResProductVariantSizeSize extends UPSPricingAttributeEcoResProductVariantSize
    implements UPSIPricingAttribute, UPSIPricingAttributeEcoResProductVariantDimensionValue
{
}

Method.Source:
public anytype getValueOfAttribute(Common _pricingObject)
{
    RefRecId sizeId = this.getTableRecord(_pricingObject).Size;
    return EcoResSize::find(sizeId).Name;
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    EcoResSize ecoResSize;
    while select Name from ecoResSize
    {
        ret.add(ecoResSize.Name);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    QueryBuildDataSource qbdsSize = _qbds.addDataSource(tableNum(EcoResSize));
    qbdsSize.joinMode(JoinMode::InnerJoin);
    qbdsSize.addLink(fieldNum(EcoResProductVariantSize, Size), fieldNum(EcoResSize, RecId));
    qbdsSize.addRange(fieldNum(EcoResSize, Name)).value(queryValue(_value));
}

public void buildEcoResProductVariantQuery(Query _query, anytype _value, QueryBuildDataSource _qbds)
{
    if (_qbds.table() != tableNum(EcoResDistinctProductVariant))
    {
        return;
    }

    QueryBuildDataSource qbdsVariantSize, qbdsSize;
    qbdsVariantSize = _qbds.addDataSource(tableNum(EcoResProductVariantSize));
    qbdsVariantSize.joinMode(JoinMode::ExistsJoin);
    qbdsVariantSize.addLink(fieldNum(EcoResDistinctProductVariant, RecId), fieldNum(EcoResProductVariantSize, DistinctProductVariant));

    qbdsSize = qbdsVariantSize.addDataSource(tableNum(EcoResSize));
    qbdsSize.joinMode(JoinMode::InnerJoin);
    qbdsSize.addLink(fieldNum(EcoResProductVariantSize,Size), fieldNum(EcoResSize, RecId));

    qbdsSize.addRange(fieldNum(EcoResSize, Name)).value(queryValue(_value));
}
